      if (version !== loadVersion) return;
      if (!Array.isArray(result.jobs)) throw new Error('任务响应不完整，请重新读取。');
      var jobs = result.jobs.filter(function (job) { return typeof job.key === 'string' && job.key.startsWith(context.userId + '/'); });
